  {
    "Name": "BucketRoleGrid",
    "Content": "async function (variables) {
	var bucketRoleGrid = new  GridWidget(variables.element, variables.dataSource);
	bucketRoleGrid.groupable = false;
	bucketRoleGrid.editable = false;
	bucketRoleGrid.change = async function(e) {
		if (!variables.SelectedB2BRoles) { variables.SelectedB2BRoles = []; }
		var bucketExists = variables.SelectedB2BRoles.filter(r => r.Id == bucket.Id).length > 0;
		if (!bucketExists) {
			var bucketEntity = await api.get("B2B/Bucket(" + bucket.Id + ")");
			variables.SelectedB2BRoles.push(bucketEntity);
		}
		variables.SelectedB2BRoles.filter(r => r.Id == bucket.Id)[0].Roles = [];
		var selectedRows = this.select();
		for (var i = 0; i < selectedRows.length; i++) {
			var dataItem = this.dataItem(selectedRows[i]);
			variables.SelectedB2BRoles.filter(r => r.Id == bucket.Id)[0].Roles.push(dataItem);
		}
		variables.SelectedB2BRoles.filter(r => r.Id == bucket.Id)[0].RolesJson = JSON.stringify(variables.SelectedB2BRoles.filter(r => r.Id == bucket.Id)[0].Roles);
	};
	bucketRoleGrid.columns = [
		{ selectable: (readonly) ? false : true, width: "50px" },
		{ field: "Name", title: "[resource_shortdisplayname[Name]]" }
	];
	variables.BucketRoleGrid = bucketRoleGrid;
}
