  {
    "Name": "CreditGrid",
    "Content": "async function (vars) {
	var g = new GridWidget(vars.element, vars.dataSource);
	g.searchable = true;
	g.search = {
		fields: ["DebtorName", "CreditorName", "Number"]
	};
	g.filterable = true;
	g.editable = false;
	g.exports = true;
	g.columns = [
		{
			field: "CreditTypeId",
			width: 100,
			title: "[resource_shortdisplayname[CreditTypeId]]",
			description: "[resource_description[CreditTypeId]]",
			template: "#= Credits.creditTypes[CreditTypeId-1].name#",
			filterable: false,
			groupable: false,
			sortable: true
		},
		{
			field: "DebtorName",
			width: 150,
			title: "[resource_shortdisplayname[DebtorName]]",
			description: "[resource_description[DebtorName]]",
			filterable: {multi: true, search: true}
		},
		{
			field: "DebtorState",
			template: "#=B2B.transactionStates[DebtorState] #",
